import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([
    [0, 0],
    [1000, 0],
    [999999, 0],
    [-500, 0],
  ])("computeDiscountCents(%i) returns %i", (subtotal, expected) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(expected);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([
      [-1, "percent must be between 0 and 100"],
      [101, "percent must be between 0 and 100"],
      [NaN, "percent must be between 0 and 100"],
      [Infinity, "percent must be between 0 and 100"],
    ])("rejects invalid percent %s", (percent, msg) => {
      expect(() => new PercentageDiscountPolicy(percent)).toThrow(RangeError);
      expect(() => new PercentageDiscountPolicy(percent)).toThrow(msg);
    });

    it("accepts boundary values 0 and 100", () => {
      expect(() => new PercentageDiscountPolicy(0)).not.toThrow();
      expect(() => new PercentageDiscountPolicy(100)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("computes 10% of 1000 = 100", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(1000)).toBe(100);
    });

    it("rounds down to nearest cent", () => {
      const policy = new PercentageDiscountPolicy(33);
      // 33% of 1000 = 330.0 (exact), 33% of 100 = 33.0 (exact)
      // 33% of 101 = 33.33 → 33
      expect(policy.computeDiscountCents(101)).toBe(33);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("100% discount equals full subtotal", () => {
      const policy = new PercentageDiscountPolicy(100);
      expect(policy.computeDiscountCents(5000)).toBe(5000);
    });

    it("0% discount returns 0", () => {
      const policy = new PercentageDiscountPolicy(0);
      expect(policy.computeDiscountCents(5000)).toBe(0);
    });

    it("handles large subtotal", () => {
      const policy = new PercentageDiscountPolicy(15);
      // 15% of 10_000_000 = 1_500_000
      expect(policy.computeDiscountCents(10_000_000)).toBe(1_500_000);
    });
  });
});

