    it("selects bracket at exact boundary", () => {
      expect(
        calc.computeShippingCents([makeLine("a", 1, 500)], 5000),
      ).toBe(300);
    });

    it("selects next bracket when just above boundary", () => {
      expect(
        calc.computeShippingCents([makeLine("a", 1, 501)], 5000),
      ).toBe(600);
    });

    it("selects highest bracket at its boundary", () => {
      expect(
        calc.computeShippingCents([makeLine("a", 1, 2000)], 5000),
      ).toBe(1000);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      expect(
        calc.computeShippingCents([makeLine("a", 1, 3000)], 5000),
      ).toBe(1500);
    });

    it("falls back to heaviest bracket cost when no overflowCostCents", () => {
      const noOverflow = new WeightBasedShippingCalculator([
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 600 },
      ]);
      expect(
        noOverflow.computeShippingCents([makeLine("a", 1, 2000)], 5000),
      ).toBe(600);
    });

    it("sorts brackets internally regardless of input order", () => {
      const unordered = new WeightBasedShippingCalculator([
        { upToGrams: 1000, costCents: 600 },
        { upToGrams: 500, costCents: 300 },
      ]);
      expect(
        unordered.computeShippingCents([makeLine("a", 1, 400)], 5000),
      ).toBe(300);
    });

    it("accumulates weight across multiple lines", () => {
      // 2 items at 300g each = 600g → second bracket
      const lines = [makeLine("a", 2, 300)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(600);
    });
  });
});

