// ── Cart pricing pipeline ────────────────────────────────────────────
describe("Cart — pricing pipeline", () => {
  it("computes subtotal as sum of unitPriceCents * quantity", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2); // 2000
    cart.add(product("b", 500), 3); // 1500
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(3500);
  });

  it("empty cart has all-zero totals", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("applies discount, then tax on discounted subtotal", () => {
    const discount = mockDiscount((s) => Math.floor(s * 0.1)); // 10% off
    const tax = mockTax((t) => Math.floor(t * 0.05)); // 5% tax
    const cart = new Cart({
      discountPolicy: discount,
      taxCalculator: tax,
    });
    cart.add(product("a", 1000), 1);
    const totals = cart.totals();
    // subtotal=1000, discount=100, discounted=900, tax=45
    expect(totals.subtotalCents).toBe(1000);
    expect(totals.discountCents).toBe(100);
    expect(totals.taxCents).toBe(45);
    expect(totals.totalCents).toBe(900 + 45);
  });

  it("clamps discount to [0, subtotal]", () => {
    // Discount returns more than subtotal
    const discount = mockDiscount(() => 9999);
    const cart = new Cart({ discountPolicy: discount });
    cart.add(product("a", 500), 1);
    const totals = cart.totals();
    expect(totals.discountCents).toBe(500); // clamped to subtotal
    expect(totals.totalCents).toBe(0);
  });

  it("clamps negative discount to 0", () => {
    const discount = mockDiscount(() => -100);
    const cart = new Cart({ discountPolicy: discount });
    cart.add(product("a", 500), 1);
    const totals = cart.totals();
    expect(totals.discountCents).toBe(0);
    expect(totals.totalCents).toBe(500);
  });

  it("clamps negative tax to 0", () => {
    const tax = mockTax(() => -50);
    const cart = new Cart({ taxCalculator: tax });
    cart.add(product("a", 500), 1);
    const totals = cart.totals();
    expect(totals.taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const shipping = mockShipping(() => -100);
    const cart = new Cart({ shippingCalculator: shipping });
    cart.add(product("a", 500), 1);
    const totals = cart.totals();
    expect(totals.shippingCents).toBe(0);
  });

  it("shipping receives discounted subtotal", () => {
    const discount = mockDiscount((s) => Math.floor(s * 0.5)); // 50% off
    const shippingFn = vi.fn(
      (_lines: readonly CartLine[], _sub: number) => 500,
    );
    const cart = new Cart({
      discountPolicy: discount,
      shippingCalculator: { computeShippingCents: shippingFn },
    });
    cart.add(product("a", 1000), 1);
    cart.totals();
    // Shipping should receive discountedSubtotal = 500
    expect(shippingFn).toHaveBeenCalledWith(expect.any(Array), 500);
  });

  it("tax calculator receives the configured region", () => {
    const taxFn = vi.fn((_t: number, _r: string) => 0);
    const cart = new Cart({
      taxCalculator: { computeTaxCents: taxFn },
      region: "FR",
    });
    cart.add(product("a", 1000), 1);
    cart.totals();
    expect(taxFn).toHaveBeenCalledWith(1000, "FR");
  });

  it("defaults region to US", () => {
    const taxFn = vi.fn((_t: number, _r: string) => 0);
    const cart = new Cart({ taxCalculator: { computeTaxCents: taxFn } });
    cart.add(product("a", 1000), 1);
    cart.totals();
    expect(taxFn).toHaveBeenCalledWith(1000, "US");
  });

  it("total = discountedSubtotal + tax + shipping", () => {
    const discount = mockDiscount(() => 200);
    const tax = mockTax(() => 80);
    const shipping = mockShipping(() => 300);
    const cart = new Cart({
      discountPolicy: discount,
      taxCalculator: tax,
      shippingCalculator: shipping,
    });
    cart.add(product("a", 1000), 1);
    const totals = cart.totals();
    // subtotal=1000, discount=200, discounted=800, tax=80, shipping=300
    expect(totals.totalCents).toBe(800 + 80 + 300);
  });
});

