import { describe, it, expect, vi, beforeEach } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product, CartLine } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import { InventoryError } from "../src/inventory.ts";

// ── helpers ──────────────────────────────────────────────────────────
const product = (
  id: string,
  unitPriceCents: number,
  weightGrams?: number,
): Product => ({ id, name: id, unitPriceCents, weightGrams });

const mockDiscount = (fn: (s: number) => number): DiscountPolicy => ({
  computeDiscountCents: vi.fn(fn),
});

const mockTax = (fn: (t: number, r: string) => number): TaxCalculator => ({
  computeTaxCents: vi.fn(fn),
});

const mockShipping = (
  fn: (l: readonly CartLine[], s: number) => number,
): ShippingCalculator => ({
  computeShippingCents: vi.fn(fn),
});

// ── Cart item management ─────────────────────────────────────────────
describe("Cart — item management", () => {
  let cart: Cart;

  beforeEach(() => {
    cart = new Cart();
  });

  it("starts with 0 items", () => {
    expect(cart.itemCount).toBe(0);
  });

  it("adds a product", () => {
    cart.add(product("a", 500), 3);
    expect(cart.itemCount).toBe(3);
  });

  it("merges quantities when adding the same product twice", () => {
    cart.add(product("a", 500), 2);
    cart.add(product("a", 500), 3);
    expect(cart.itemCount).toBe(5);
  });

  it("rejects non-positive quantity on add", () => {
    expect(() => cart.add(product("a", 500), 0)).toThrow(RangeError);
    expect(() => cart.add(product("a", 500), -1)).toThrow(RangeError);
  });

  it("rejects non-integer quantity on add", () => {
    expect(() => cart.add(product("a", 500), 1.5)).toThrow(RangeError);
  });

  it("rejects negative unitPriceCents on add", () => {
    expect(() => cart.add(product("a", -1), 1)).toThrow(RangeError);
  });

  it("remove returns true for existing product", () => {
    cart.add(product("a", 500), 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove returns false for unknown product", () => {
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity changes the line quantity", () => {
    cart.add(product("a", 500), 3);
    cart.updateQuantity("a", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("updateQuantity to 0 removes the line", () => {
    cart.add(product("a", 500), 3);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
  });

  it("updateQuantity rejects negative quantity", () => {
    cart.add(product("a", 500), 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("updateQuantity rejects non-integer quantity", () => {
    cart.add(product("a", 500), 1);
    expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
  });

  it("updateQuantity throws for unknown product", () => {
    expect(() => cart.updateQuantity("nope", 1)).toThrow(
      "Product nope is not in the cart",
    );
  });

  it("clear removes all lines", () => {
    cart.add(product("a", 500), 2);
    cart.add(product("b", 300), 1);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot returns a deep copy", () => {
    cart.add(product("a", 500), 2);
    const snap = cart.snapshot();
    // Mutating the snapshot should not affect the cart
    (snap[0] as CartLine).quantity = 999;
    expect(cart.itemCount).toBe(2);
  });
});

// ── Cart pricing pipeline ────────────────────────────────────────────
describe("Cart — pricing pipeline", () => {
  it("computes subtotal as sum of unitPriceCents * quantity", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2); // 2000
    cart.add(product("b", 500), 3); // 1500
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(3500);
  });

  it("empty cart has all-zero totals", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("applies discount, then tax on discounted subtotal", () => {
    const discount = mockDiscount((s) => Math.floor(s * 0.1)); // 10% off
    const tax = mockTax((t) => Math.floor(t * 0.05)); // 5% tax
    const cart = new Cart({
      discountPolicy: discount,
      taxCalculator: tax,
    });
    cart.add(product("a", 1000), 1);
    const totals = cart.totals();
    // subtotal=1000, discount=100, discounted=900, tax=45
    expect(totals.subtotalCents).toBe(1000);
    expect(totals.discountCents).toBe(100);
    expect(totals.taxCents).toBe(45);
    expect(totals.totalCents).toBe(900 + 45);
  });

  it("clamps discount to [0, subtotal]", () => {
    // Discount returns more than subtotal
    const discount = mockDiscount(() => 9999);
    const cart = new Cart({ discountPolicy: discount });
    cart.add(product("a", 500), 1);
    const totals = cart.totals();
    expect(totals.discountCents).toBe(500); // clamped to subtotal
    expect(totals.totalCents).toBe(0);
  });

  it("clamps negative discount to 0", () => {
    const discount = mockDiscount(() => -100);
    const cart = new Cart({ discountPolicy: discount });
    cart.add(product("a", 500), 1);
    const totals = cart.totals();
    expect(totals.discountCents).toBe(0);
    expect(totals.totalCents).toBe(500);
  });

  it("clamps negative tax to 0", () => {
    const tax = mockTax(() => -50);
    const cart = new Cart({ taxCalculator: tax });
    cart.add(product("a", 500), 1);
    const totals = cart.totals();
    expect(totals.taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const shipping = mockShipping(() => -100);
    const cart = new Cart({ shippingCalculator: shipping });
    cart.add(product("a", 500), 1);
    const totals = cart.totals();
    expect(totals.shippingCents).toBe(0);
  });

  it("shipping receives discounted subtotal", () => {
    const discount = mockDiscount((s) => Math.floor(s * 0.5)); // 50% off
    const shippingFn = vi.fn(
      (_lines: readonly CartLine[], _sub: number) => 500,
    );
    const cart = new Cart({
      discountPolicy: discount,
      shippingCalculator: { computeShippingCents: shippingFn },
    });
    cart.add(product("a", 1000), 1);
    cart.totals();
    // Shipping should receive discountedSubtotal = 500
    expect(shippingFn).toHaveBeenCalledWith(expect.any(Array), 500);
  });

  it("tax calculator receives the configured region", () => {
    const taxFn = vi.fn((_t: number, _r: string) => 0);
    const cart = new Cart({
      taxCalculator: { computeTaxCents: taxFn },
      region: "FR",
    });
    cart.add(product("a", 1000), 1);
    cart.totals();
    expect(taxFn).toHaveBeenCalledWith(1000, "FR");
  });

  it("defaults region to US", () => {
    const taxFn = vi.fn((_t: number, _r: string) => 0);
    const cart = new Cart({ taxCalculator: { computeTaxCents: taxFn } });
    cart.add(product("a", 1000), 1);
    cart.totals();
    expect(taxFn).toHaveBeenCalledWith(1000, "US");
  });

  it("total = discountedSubtotal + tax + shipping", () => {
    const discount = mockDiscount(() => 200);
    const tax = mockTax(() => 80);
    const shipping = mockShipping(() => 300);
    const cart = new Cart({
      discountPolicy: discount,
      taxCalculator: tax,
      shippingCalculator: shipping,
    });
    cart.add(product("a", 1000), 1);
    const totals = cart.totals();
    // subtotal=1000, discount=200, discounted=800, tax=80, shipping=300
    expect(totals.totalCents).toBe(800 + 80 + 300);
  });
});

// ── Cart.checkout() ──────────────────────────────────────────────────
describe("Cart — checkout", () => {
  it("returns totals and lines without collaborators", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.lines).toHaveLength(1);
    expect(result.lines[0]!.product.id).toBe("a");
  });

  it("refreshes prices when priceFetcher is provided", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };
    const result = await cart.checkout({ priceFetcher });
    expect(result.totals.subtotalCents).toBe(1500);
    expect(result.lines[0]!.product.unitPriceCents).toBe(1500);
  });

  it("throws InventoryError when item is unavailable", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: false, reason: "sold out" }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const ie = err as InventoryError;
      expect(ie.productId).toBe("a");
      expect(ie.requested).toBe(5);
      expect(ie.message).toBe("sold out");
    }
  });

  it("throws InventoryError on partial-stock denial", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 10);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const ie = err as InventoryError;
      expect(ie.productId).toBe("a");
      expect(ie.requested).toBe(10);
      expect(ie.available).toBe(3);
    }
  });

  it("passes when inventory says available with sufficient quantity", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("passes when inventory says available without availableQuantity", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("uses asyncTaxProvider for tax computation when provided", async () => {
    const discount = mockDiscount(() => 0);
    const cart = new Cart({ discountPolicy: discount });
    cart.add(product("a", 1000), 1);
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const result = await cart.checkout({ asyncTaxProvider });
    // tax = floor(1000 * 0.1) = 100
    expect(result.totals.taxCents).toBe(100);
    expect(result.totals.totalCents).toBe(1000 + 100);
  });

  it("async tax uses discounted subtotal", async () => {
    const discount = mockDiscount((s) => Math.floor(s * 0.2)); // 20% off
    const cart = new Cart({ discountPolicy: discount });
    cart.add(product("a", 1000), 1);
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const result = await cart.checkout({ asyncTaxProvider });
    // subtotal=1000, discount=200, discounted=800, tax=floor(800*0.1)=80
    expect(result.totals.discountCents).toBe(200);
    expect(result.totals.taxCents).toBe(80);
  });

  it("combines priceFetcher + inventoryChecker + asyncTaxProvider", async () => {
    const shipping = mockShipping(() => 500);
    const cart = new Cart({ shippingCalculator: shipping });
    cart.add(product("a", 1000), 2);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(800),
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.05),
    };

    const result = await cart.checkout({
      priceFetcher,
      inventoryChecker,
      asyncTaxProvider,
    });
    // New price: 800 * 2 = 1600, no discount, tax = floor(1600*0.05) = 80
    expect(result.totals.subtotalCents).toBe(1600);
    expect(result.totals.taxCents).toBe(80);
    expect(result.totals.shippingCents).toBe(500);
    expect(result.totals.totalCents).toBe(1600 + 80 + 500);
  });

  it("generates default InventoryError message when reason is undefined", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        availableQuantity: 2,
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const ie = err as InventoryError;
      expect(ie.message).toContain("insufficient stock");
      expect(ie.message).toContain("a");
      expect(ie.available).toBe(2);
    }
  });

  it("first inventory denial wins when cart has multiple items", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    cart.add(product("b", 2000), 1);
    const inventoryChecker: InventoryChecker = {
      check: vi
        .fn()
        .mockResolvedValueOnce({ available: true })
        .mockResolvedValueOnce({ available: false, reason: "b is out" }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      expect((err as InventoryError).productId).toBe("b");
    }
  });
});

